31	  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
32	    if (process.env.DSH_CLI_MOCK_FAILURE === '1') {
33	      yield { type: 'finish', reason: { kind: 'error', failure: { code: 'SERVER', message: 'CLI mock provider failed' } } }
34	      return
35	    }
36	    const toolResult = options.messages.at(-1)?.content.find(block => block.type === 'tool-result')
37	    if (toolResult === undefined) {
38	      const args = JSON.stringify({ command: 'printf CLI_TOOL_ROUND_TRIP', description: 'Prove the CLI tool round trip.' })
39	      yield { type: 'block-start', index: 0, blockType: 'tool-call' }
40	      yield { type: 'tool-call-delta', index: 0, id: CallId('cli-smoke-call'), name: 'bash', argumentsDelta: args }
41	      yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: CallId('cli-smoke-call'), name: 'bash', arguments: args } }
42	      yield { type: 'usage', usage: { inputTokens: 11, outputTokens: 3, cacheReadTokens: 2 } }
43	      yield { type: 'finish', reason: { kind: 'tool-calls' } }
44	      return
45	    }
46	
47	    const toolText = toolResult.content
48	      .filter(block => block.type === 'text')
49	      .map(block => block.text)
50	      .join('')
51	    const reply = `CLI tool round trip complete: ${toolText.trim()}`
52	    yield { type: 'block-start', index: 0, blockType: 'text' }
53	    yield { type: 'text-delta', index: 0, text: reply }
54	    yield { type: 'block-end', index: 0, block: { type: 'text', text: reply } }
55	    yield { type: 'usage', usage: { inputTokens: 7, outputTokens: 5, reasoningTokens: 1 } }
56	    yield { type: 'finish', reason: { kind: 'stop' } }
57	  }
58	}
